    p = Symbol('p', positive=True)
    assert Factors({r**2: S.Half}).as_expr() == abs(r)
    assert Factors({p**2: S.Half}).as_expr() == p
    for exponent in (2, -2, S(2), S(-2)):
        assert Factors({x**y: exponent}).as_expr() == x**(exponent*y)


